 {id:'studio',file:'studio.txt',name:'Design services',scenario:'Clean invoice',vendor:'Studio Eight',number:'SE-208',due:'2026-12-15',subtotal:1250,tax:0,total:1250,lines:'Brand design · 10 hours × $125.00 = $1,250.00'},
 {id:'duplicate',file:'northstar-copy.txt',name:'Resent office invoice',scenario:'Duplicate detection',vendor:'Northstar Paper Co.',number:'NS-1042',due:'2026-12-12',subtotal:480,tax:38.4,total:518.4,lines:'Copy paper · 12 boxes × $25.00 = $300.00\nDesk supplies · 6 sets × $30.00 = $180.00'},
 {id:'freight',file:'freight.txt',name:'Delivery services',scenario:'Total mismatch',vendor:'Harbor Freight Services',number:'HF-773',due:'2026-12-18',subtotal:850,tax:68,total:968,lines:'Local deliveries · 10 trips × $85.00 = $850.00'},
 {id:'cloud',file:'cloud.txt',name:'Software subscription',scenario:'Missing information',vendor:'Cloudline Software',number:'CL-091',due:'',subtotal:299,tax:0,total:299,lowConfidence:true,lines:'Team subscription · 1 month × $299.00 = $299.00'}
