export function sourceText(s){return `FICTIONAL SAMPLE — DEMO ONLY\n\nINVOICE\nVendor: ${s.vendor}\nInvoice: ${s.number}\nIssued: 2026-11-12\nDue: ${s.due}\nBill to: Oak & Elm Creative (fictional)\nCurrency: USD\n\n${s.lines}\n\nSubtotal: ${s.subtotal.toFixed(2)}\nTax: ${s.tax.toFixed(2)}\nTotal: ${s.total.toFixed(2)}\n\n${s.id==='cloud'?'Due date omitted intentionally. For this exercise, use 2026-12-12 after confirming with the fictional vendor.':s.id==='freight'?'Training scenario: the vendor total is incorrect. Use $918.00 as the corrected total.':'Thank you for your business.'}\n`;}
export function newDocs(){return samples.map(s=>({id:s.id,name:s.name,file:s.file,scenario:s.scenario,source:sourceText(s),fields:{vendor:s.vendor,number:s.number,due:s.due,subtotal:s.subtotal,tax:s.tax,total:s.total},status:'queued',lowConfidence:!!s.lowConfidence,verified:false}));}
